import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

public class Main {
    static final long MOD = 998244353L;
    static long[] f = new long[500010];
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer st;

    static String readLine() throws IOException {
        return br.readLine();
    }

    static int readInt() throws IOException {
        return Integer.parseInt(readLine());
    }

    static long readLong() throws IOException {
        return Long.parseLong(readLine());
    }

    static double readDouble() throws IOException {
        return Double.parseDouble(readLine());
    }

    static List<String> readStrings() throws IOException {
        String line = readLine();
        String[] parts = line.split(" ");
        List<String> list = new ArrayList<>();
        for (String s : parts) list.add(s);
        return list;
    }

    static List<Integer> readInts() throws IOException {
        List<String> strings = readStrings();
        List<Integer> ints = new ArrayList<>();
        for (String s : strings) ints.add(Integer.parseInt(s));
        return ints;
    }

    static List<Long> readLongs() throws IOException {
        List<String> strings = readStrings();
        List<Long> longs = new ArrayList<>();
        for (String s : strings) longs.add(Long.parseLong(s));
        return longs;
    }

    static List<Double> readDoubles() throws IOException {
        List<String> strings = readStrings();
        List<Double> doubles = new ArrayList<>();
        for (String s : strings) doubles.add(Double.parseDouble(s));
        return doubles;
    }

    static long pw(long a, long b) {
        long c = b;
        long d = a;
        long res = 1L;
        while (c > 0) {
            if ((c & 1L) != 0L) {
                res *= d;
                res %= MOD;
            }
            d *= d;
            d %= MOD;
            c /= 2;
        }
        return res;
    }

    static long inv(long a) {
        return pw(a, MOD - 2L);
    }

    public static void main(String[] args) throws IOException {
        f[0] = 1L;
        f[1] = 1L;
        for (int i = 2; i <= 500000; i++) {
            f[i] = f[i - 1] * i % MOD;
        }

        int tt = 1;
        while (tt-- > 0) {
            List<Integer> nk = readInts();
            int n = nk.get(0);
            int k = nk.get(1);
            long ans = 0L;
            for (int i = 1; i <= n - k + 1; i++) {
                int cnt = n / i;
                if (cnt < k) {
                    continue;
                }
                long sum = f[cnt - 1] * inv(f[k - 1]) % MOD;
                sum = inv(f[cnt - k]) * sum % MOD;
                ans += sum;
                ans %= MOD;
            }
            System.out.println(ans);
        }
    }
}

